// One item per uploaded file, each carrying its binary under the key 'file'.
const item = $input.first();
return (item.json.files ?? []).map(f => ({
  json: { file_name: f.fileName },
  binary: { file: item.binary[f.binaryKey] },
}));

const files = $('Split Files').all();
const parts = $input.all().map((item, i) => {
  const name = files[i]?.json.file_name ?? `file ${i + 1}`;
  const res = item.json;
  if (res.error && res.statusCode === undefined) {
    return `**${name}**: Error: analysis service unreachable (${res.error.message ?? res.error}).`;
  }
  const body = res.body ?? {};
  if (res.statusCode !== 200) {
    const e = body.error ?? {};
    return `**${name}**: Error ${e.code ?? res.statusCode}: ${e.message ?? 'request failed'}${e.hint ? ` (${e.hint})` : ''}`;
  }
  const lines = [`**${name}** added as \`${body.doc_id}\`: ${body.chunks} passages${body.pages ? ` from ${body.pages} pages` : ''}.`];
  for (const w of body.warnings ?? []) lines.push(`- Warning: ${w}`);
  return lines.join('\n');
});
return [{ json: { output: parts.join('\n\n') } }];

// Turns search results into an Ollama chat request, or a direct reply when there is nothing to ask.
const res = $input.first().json;
const question = ($('Chat Trigger').first().json.chatInput ?? '').trim();
if (res.error && res.statusCode === undefined) {
  return [{ json: { ask: false, output: `Error: analysis service unreachable (${res.error.message ?? res.error}).` } }];
}
const body = res.body ?? {};
if (res.statusCode !== 200) {
  const e = body.error ?? {};
  return [{ json: { ask: false, output: `Error ${e.code ?? res.statusCode}: ${e.message ?? 'search failed'}${e.hint ? ` (${e.hint})` : ''}` } }];
}
const sources = body.results ?? [];
const notes = (body.warnings ?? []).map(w => `\n\n_Note: ${w}_`).join('');
if (!sources.length) {
  return [{ json: { ask: false, output: 'The knowledge base is empty. Attach TXT or PDF documents to add them.' + notes } }];
}
const context = sources.map((s, i) =>
  `[${i + 1}] ${s.file_name}${s.page ? `, page ${s.page}` : ''}\n${s.text}`).join('\n\n');
const request = {
  model: 'qwen2.5:3b',
  stream: false,
  options: { temperature: 0 },
  format: {
    type: 'object',
    properties: {
      answer: { type: 'string' },
      sources: { type: 'array', items: { type: 'integer' } },
    },
    required: ['answer', 'sources'],
  },
  messages: [
    {
      role: 'system',
      content: 'You answer questions using only the numbered sources provided. ' +
        'Never use outside knowledge and never guess. ' +
        'If the sources do not contain the answer, set answer to "I could not find this in the knowledge base." and sources to []. ' +
        'Otherwise answer concisely, quote figures exactly as written, and list in sources the numbers of every source you used.',
    },
    { role: 'user', content: `Sources:\n\n${context}\n\nQuestion: ${question}` },
  ],
};
return [{ json: { ask: true, request, sources, notes } }];

const prep = $('Build Prompt').first().json;
const res = $input.first().json;
if (res.statusCode !== 200) {
  const detail = res.body?.error ?? res.error?.message ?? res.statusCode;
  return [{ json: { output: `Error: the language model call failed (${typeof detail === 'string' ? detail : JSON.stringify(detail)}).` } }];
}
let out;
try {
  out = JSON.parse(res.body.message.content);
} catch {
  return [{ json: { output: 'Error: the language model returned an unreadable answer.' } }];
}
const cited = [...new Set((out.sources ?? []).filter(n => Number.isInteger(n) && n >= 1 && n <= prep.sources.length))];
let text = String(out.answer ?? '').trim();
if (cited.length) {
  text += '\n\n**Sources**\n' + cited.map(n => {
    const s = prep.sources[n - 1];
    return `- [${n}] ${s.file_name}${s.page ? `, page ${s.page}` : ''}`;
  }).join('\n');
} else if (!/could not find/i.test(text)) {
  text += '\n\n_The model cited no source for this answer; treat it as unverified._';
}
return [{ json: { output: text + prep.notes } }];
